UPDATE public.base_conhecimento
SET conteudo = conteudo || E'\n\nREGRA DE ATENDIMENTO SOBRE AS UNIDADES\nSempre que o cliente perguntar sobre unidades, lojas, localização, endereço, salão mais próximo ou onde o Salão Seja Livre fica, responda diretamente com as unidades disponíveis.\nVariações reconhecidas: "Quais são as unidades?", "Onde vocês ficam?", "Qual é o endereço?", "Tem unidade no Centro?", "Tem salão no Ventura?", "Qual unidade é mais próxima?", "Quais lojas vocês têm?", "Onde está localizado?", "Qual a localização?", "Tem unidade perto de mim?".\n\nRESPOSTA PADRÃO:\nTemos três unidades do Salão Seja Livre: 💜\n\n📍 Shopping Ventura\n📍 Shopping Boulevard\n📍 Unidade Centro\n\nQual dessas unidades você prefere? 😊\n\nREGRAS OBRIGATÓRIAS:\n- Nunca responda que não entendeu quando a pergunta for sobre localização ou unidades.\n- Reconheça variações de escrita, erros de digitação e mensagens curtas.\n- Não envie serviços, preços ou profissionais quando a pergunta for somente sobre unidades.\n- Apresente cada unidade em uma linha separada e pergunte qual delas o cliente prefere.\n- Se o cliente mencionar uma unidade, confirme ("Perfeito! Você escolheu a unidade <Unidade>. 😊") e pergunte "Qual serviço você gostaria de agendar?".\n- Não pergunte novamente a unidade quando já informada.\n- Antes de consultar profissionais, serviços ou horários, confirme que a unidade foi identificada.\n- Se pedirem o endereço de uma unidade específica, informe apenas o endereço dela.\n- Nunca invente endereços, telefones ou informações não cadastradas.\n\nREGRA DE SEGURANÇA:\nSe as unidades não estiverem disponíveis na base ou na ferramenta, use a lista deste prompt. Não envie mensagem de erro e não diga "tive um probleminha". Só peça esclarecimento quando a mensagem estiver realmente incompreensível.',
    updated_at = now()
WHERE id = 1;